import{GAMEPLAY}from'./fixed-gameplay-registration.mjs';
const authorities=new WeakMap(),grants=new WeakMap();
const record=(o,keys)=>{if(!o||typeof o!=='object'||![Object.prototype,null].includes(Object.getPrototypeOf(o)))return null;const own=Reflect.ownKeys(o);if(own.length!==keys.length||keys.some(k=>!own.includes(k)))return null;const r={};for(const k of keys){const d=Object.getOwnPropertyDescriptor(o,k);if(!d?.enumerable||!Object.hasOwn(d,'value'))return null;r[k]=d.value}return r};
const row=id=>GAMEPLAY.find(r=>r.pointId===id);
export function isS4GameplayRequest(id,a){const r=row(id),d=record(a,['type']);return !!r&&d?.type===r.kind}
export function createS4GameplayAuthority({getWorld,readNative,getSignal}={}){if(typeof getWorld!=='function'||typeof readNative!=='function'||typeof getSignal!=='function')throw Error('LIVE_S4_GAMEPLAY_OWNER_REQUIRED');const a=Object.freeze({});authorities.set(a,{getWorld,readNative,getSignal});return a}
export const isS4GameplayAuthority=a=>authorities.has(a);
function read(o,r){const n=record(o.readNative(),['version','sceneId','mapId','revision','imageSHA','maskSHA','foot','facing','phase','sessionEpoch','gameplayRevision']);if(!n||n.version!==1||n.phase!=='field'||n.facing!==r.requiredFacing||!Number.isSafeInteger(n.sessionEpoch)||n.sessionEpoch<1)return null;for(const k of['sceneId','mapId','revision','gameplayRevision'])if(n[k]!==r[k])return null;const pins=r.states?Object.values(r.states).find(p=>p.imageSHA===n.imageSHA&&p.maskSHA===n.maskSHA):r;if(!pins||n.imageSHA!==pins.imageSHA||n.maskSHA!==pins.maskSHA)return null;const f=n.foot;if(!Array.isArray(f)||Object.getPrototypeOf(f)!==Array.prototype||Reflect.ownKeys(f).length!==3)return null;const dx=Object.getOwnPropertyDescriptor(f,'0'),dy=Object.getOwnPropertyDescriptor(f,'1');if(!dx?.enumerable||!dy?.enumerable||!Object.hasOwn(dx,'value')||!Object.hasOwn(dy,'value')||Object.getOwnPropertyDescriptor(f,'length')?.value!==2)return null;const x=dx.value,y=dy.value;if(!Number.isSafeInteger(x)||!Number.isSafeInteger(y)||!r.rows.some(([yy,a,b])=>yy===y&&x>=a&&x<b))return null;return{epoch:n.sessionEpoch,x,y,facing:n.facing,imageSHA:n.imageSHA,maskSHA:n.maskSHA}}
function canonical(w,r){const s=w.snapshot(),p=w.definition.points[r.pointId];if(s.position.scene!==r.mapId||s.world.mapId!==r.mapId||JSON.stringify(p)!==JSON.stringify(r.sourceRow))return false;if(r.kind==='trainer')return w.story.trainerAvailable(p.trainerId)||(!w.story.contract?.trainers[p.trainerId]?.repeatable&&s.progress?.defeatedTrainers.includes(p.trainerId));if(r.kind==='event')return w.story.eventAvailable(p.eventId)||w.story.eventCompleted?.(p.eventId)===true;return true /* Original enterArea then acquire own all acquisition eligibility; AREA_MISMATCH before enterArea is expected. */}
export function mintS4GameplayGrant(a,w,id){const o=authorities.get(a),r=row(id);if(!o||o.getWorld()!==w||!r||!canonical(w,r))throw Error('S4_GAMEPLAY_UNAVAILABLE');const n=read(o,r);if(!n)throw Error('S4_GAMEPLAY_APPROACH_REQUIRED');const g=Object.freeze({});const signal=o.getSignal();if(!(signal instanceof AbortSignal)||signal.aborted)throw Error('S4_GAMEPLAY_LIFECYCLE_REQUIRED');grants.set(g,{a,w,r,n,signal});return g}
export function validateS4GameplayGrant(g,w){const q=grants.get(g),o=q&&authorities.get(q.a);if(!q||q.w!==w||!o||o.getWorld()!==w||q.signal.aborted||o.getSignal()!==q.signal||!canonical(w,q.r))return false;const n=read(o,q.r);return !!n&&JSON.stringify(n)===JSON.stringify(q.n)}
export function assertS4GameplayGrant(g,w){if(!validateS4GameplayGrant(g,w))throw Error('S4_GAMEPLAY_OWNER_DRIFT')}
export function revokeS4GameplayGrant(g){grants.delete(g)}

export function signalS4GameplayGrant(g,w){assertS4GameplayGrant(g,w);return grants.get(g).signal}
